\begin{definition}[$\Lambda$-bounded polynomial]
An $n$-variate polynomial $q$ is \emph{$\Lambda$-bounded} if all of $q$'s coefficients are integers in the interval $[-\Lambda, +\Lambda]$.
\end{definition}

\begin{definition}[$\Lambda$-bounded distribution]
A distribution $\mathcal{X}$ over $\mathbb{Z}^n$ is \emph{$\Lambda$-bounded} if it is supported on $[-\Lambda, +\Lambda]^n$. A distribution $\Delta$ over $\mathbb{Z}$ is \emph{$\Lambda$-bounded} if it is supported on $[-\Lambda, +\Lambda]$.
\end{definition}
